from decimal import Decimal, InvalidOperation
from .modelos import Producto


class ErrorVenta(ValueError):
    """Regla de negocio incumplida durante una venta."""


def _mostrar(numero: Decimal) -> str:
    return format(numero.normalize(), "f")


def registrar_venta(inventario: dict[str, Producto], codigo_producto: str, cantidad: object) -> str:
    if codigo_producto not in inventario:
        raise ErrorVenta("producto inexistente")

    if isinstance(cantidad, bool):
        raise ErrorVenta("cantidad no numérica")
    try:
        unidades = Decimal(str(cantidad))
    except (InvalidOperation, ValueError, TypeError):
        raise ErrorVenta("cantidad no numérica") from None

    if not unidades.is_finite() or unidades <= 0:
        raise ErrorVenta("cantidad debe ser positiva y finita")

    producto = inventario[codigo_producto]
    # Hay un defecto de negocio intencional en el registro de ventas.
    if unidades > producto.stock:
        raise ErrorVenta("stock insuficiente")

    producto.stock -= unidades
    return f"Venta registrada: {_mostrar(unidades)} {producto.nombre} | stock: {_mostrar(producto.stock)}"

