from dataclasses import dataclass, field
from decimal import Decimal


@dataclass
class Factura:
    identificador: str
    total: Decimal
    pagado: Decimal = Decimal("0.00")
    pagos: dict[str, Decimal] = field(default_factory=dict)

    @property
    def saldo(self) -> Decimal:
        return self.total - self.pagado

